			$(document).ready(function () {
				setWidgetServiceClicking($("#widgetShareHeader6d48fc97-52a0-4085-ba57-46cf998a76ab"), true, function () {
					var $widgetBody = $('#widgetShareBody6d48fc97-52a0-4085-ba57-46cf998a76ab');

					if ($widgetBody.is(':visible')) {
						var menuItems = $('.widgetItem a', $widgetBody);

						$(menuItems[0]).focus();

						$('.widgetItem', $widgetBody).unbind("keydown").bind("keydown", function (e) {

							if (e.which === 9) {
								var index = menuItems.index(e.target);

								if ((index === 0 && e.shiftKey) || (index === (menuItems.length - 1) && !e.shiftKey)) {
									$("#widgetShareHeader6d48fc97-52a0-4085-ba57-46cf998a76ab").trigger('click').focus();
								}
							}
			});
					} else {
						$('.widgetItem', $widgetBody).unbind("keydown");
					}
				});
			});

			$(document).ready(function () {
				setWidgetServiceClicking($("#widgetSiteToolsHeader7bee37a8-aa9d-4cc1-8a27-70e8623a2891"), true, function () {
					var $widgetBody = $('#widgetSiteToolsBody7bee37a8-aa9d-4cc1-8a27-70e8623a2891');

					if ($widgetBody.is(':visible')) {
						var menuItems = $('.widgetItem a', $widgetBody);

						$(menuItems[0]).focus();

						$('.widgetItem', $widgetBody).unbind("keydown").bind("keydown", function (e) {

							if (e.which === 9) {
								var index = menuItems.index(e.target);

								if ((index === 0 && e.shiftKey) || (index === (menuItems.length - 1) && !e.shiftKey)) {
									$("#widgetSiteToolsHeader7bee37a8-aa9d-4cc1-8a27-70e8623a2891").trigger('click').focus();
								}
							}
						});
					} else {
						$('.widgetItem', $widgetBody).unbind("keydown");
					}
				});
			});

		$(document).ready(function () {
			try {
				$(".widgetSearchButton.widgetSearchButtonfb114745-1493-4d65-98c8-28ec910841e5").click(function (e) {
				e.preventDefault();
					if (false||$("#ysnSearchOnlyDeptfb114745-1493-4d65-98c8-28ec910841e5").is(':checked'))
					{
						doWidgetSearch($(this).siblings(".widgetSearchBox").val(), Number(0));
					}
					else {
						doWidgetSearch($(this).siblings(".widgetSearchBox").val(), 0);
					}
			});
			$("#searchFieldfb114745-1493-4d65-98c8-28ec910841e5").keypress(function (e) {
				if (window.clipboardData) {
					if (e.keyCode === 13) {
						if ($("#ysnSearchOnlyDeptfb114745-1493-4d65-98c8-28ec910841e5").is(':checked') || false) {
								doWidgetSearch($(this).val(), Number(0));
							} else {
								doWidgetSearch($(this).val(), 0);
							}
						return false;
					}
				} else {
					if (e.which === 13) {
						if ($("#ysnSearchOnlyDeptfb114745-1493-4d65-98c8-28ec910841e5").is(':checked') || false) {
								doWidgetSearch($(this).val(), Number(0));
							} else {
								doWidgetSearch($(this).val(), 0);
							}
						return false;
					}
				}
				return true;
			});

				if (true) {
					var currentRequest = null;
					var $searchField = $("#searchFieldfb114745-1493-4d65-98c8-28ec910841e5").autocomplete({
						source: function (request, response) {
							currentRequest = $.ajax({
								url: '/Search/AutoComplete' + ($("#ysnSearchOnlyDeptfb114745-1493-4d65-98c8-28ec910841e5").is(':checked') || false? '?departmentId=0' : ''),
								dataType: "json",
								timeout: 10000,
								beforeSend: function () {
									if (currentRequest != null) {
										currentRequest.abort();
									}
								},
								data:
								{
									term: request.term,
								},
								success: function (data) {
									response(data);
									$('.autoCompleteError').remove();
								},
								error: function (xmlhttprequest, textstatus, message) {
									if (textstatus === "timeout") {
										if ($("#searchFieldfb114745-1493-4d65-98c8-28ec910841e5").siblings('.autoCompleteError').length == 0)
											$('
Search autocomplete is currently not responding. Please try again later.').insertAfter($("#searchFieldfb114745-1493-4d65-98c8-28ec910841e5"));
									}
								}
							});
						},
						html: true,
						delay: 500,
						select: function (event, ui) {
							$(this).val(ui.item.value);
							$(this).next().click();
						}
					});

					$searchField.data("ui-autocomplete")._renderItem = function (ul, item) {
						return $("
")
							.data("ui-autocomplete-item", item)
							.append("" + item.label + "")
							.appendTo(ul);
					};
}
}
			catch(e) {} //we're going to eat this error. Autocomplete won't work but we dont wan't to break anything else on the page.
		});

