//Updates search icons href to have the correct queryString
function searchBtnApplyQuery() {
	document.getElementById("btnSearchIcon").href = "/Search?searchPhrase=" + document.getElementById("searchFieldfb114745-1493-4d65-98c8-28ec910841e5").value;
}

nav.script:
		(function () {
			function setupMenu() {
				const menuID = 'mainNavMenu';
				const menuType = MAIN_MENU;

				//setup menu manager properties for main menu
				if (!menuManager.mobileMainNav && true)
					menuManager.adjustMainItemsWidth('#' + menuID);
				menuManager.isMainMenuEditable = false;
				menuManager.mainMenuMaxSubMenuLevels = 4;
				menuManager.setMOMMode(2, menuType);

				//Init main menu
				const setupDraggable = menuManager.isMainMenuEditable;
				const urlToGetHiddenMenus = '/Pages/MenuMain/HiddenMainSubMenus?pageID=1&moduleID=37&themeID=1&menuContainerID=mainNav';

				menuManager.setupMenu(menuID, 'mainNav', menuType, setupDraggable, urlToGetHiddenMenus);
				menuManager.mainMenuInit = true;
				menuManager.mainMenuTextResizer = true;
				if (1.00 > 0)
					menuManager.mainMenuTextResizerRatio = 1.00;
				if (window.isResponsiveEnabled)
					menuManager.mainMenuReady.resolve();

			}

			if (document.readyState === "complete"
				|| document.readyState === "loaded"
				|| document.readyState === "interactive") {
				setupMenu();
				return;
			}

			document.addEventListener("DOMContentLoaded", setupMenu);
		})();

window.addEventListener('load', function () {
	//setup menu manager properties for secondary menu
	menuManager.isSideMenuEditable = false;
	menuManager.sideMenuMaxSubMenuLevels = 4;
	menuManager.sideMenuHasCustomLinks = true;
});

window.addEventListener('load', function () {
	//Init secondary menu
	var setupDraggable = menuManager.isSideMenuEditable;
	var urlToGetHiddenMenus = '/Pages/MenuSecondary/HiddenSecondarySubMenus?pageID=1&moduleID=37&themeID=1&menuContainerID=secondaryNav';
	var menuID = 'secondaryMenusecondaryNav';
	menuManager.setMOMMode(2, SIDE_MENU);
	menuManager.setupMenu(menuID, 'secondaryNav', SIDE_MENU, setupDraggable, urlToGetHiddenMenus);
});

